begin;

-- 1. Signed-in web pages opened from the Mini Program: a one-time, one-minute ticket bound to a fresh WeChat proof.
do $kind$
declare name text;
begin
  select c.conname into name from pg_constraint c
  where c.conrelid='public.wechat_oauth_tickets'::regclass and c.contype='c' and pg_get_constraintdef(c.oid) like '%kind%';
  if name is null then raise exception 'WECHAT_TICKET_KIND_CHECK_MISSING'; end if;
  execute format('alter table public.wechat_oauth_tickets drop constraint %I', name);
end $kind$;
alter table public.wechat_oauth_tickets add constraint wechat_oauth_tickets_kind_check
  check (kind in ('flow','state','guest','grant','access','completion','miniapp_web'));

-- 2. Files a family chooses in a runtime form. Objects are private; the owner and staff who handle requests read them through signed links.
create table public.miniapp_runtime_uploads (
  id uuid primary key, owner_id uuid not null references public.profiles(id), object_path text not null unique,
  name text not null check(char_length(name) between 1 and 200), kind text not null check(kind in ('image','video','file')),
  mime_type text not null, bytes bigint not null check(bytes>0), ready boolean not null default false, created_at timestamptz not null default now()
);
create index miniapp_runtime_uploads_owner on public.miniapp_runtime_uploads(owner_id,created_at desc);
alter table public.miniapp_runtime_uploads enable row level security;
revoke all on public.miniapp_runtime_uploads from public,anon,authenticated;
grant select on public.miniapp_runtime_uploads to authenticated;
create policy miniapp_runtime_uploads_read on public.miniapp_runtime_uploads for select to authenticated using(
  owner_id=(select auth.uid()) or coalesce(public.has_perm((select auth.uid()),'organization.profile.manage'),false));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('miniapp-runtime-uploads','miniapp-runtime-uploads',false,67108864,
  array['image/jpeg','image/png','image/webp','image/heic','video/mp4','video/quicktime','application/pdf']);
insert into public.file_policies(bucket_id,purpose,access_mode,upload_protocol,max_bytes,owner_quota_bytes,allowed_mime_types,orphan_grace_hours,retention_days,malicious_content_policy)
values('miniapp-runtime-uploads','Files chosen by families in Mini Program forms','signed','standard',67108864,1073741824,
  array['image/jpeg','image/png','image/webp','image/heic','video/mp4','video/quicktime','application/pdf'],24,730,'signature_only');

-- 3. Audio and video placed on published runtime screens by staff. Read access follows publication, like content images.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('miniapp-content-media','miniapp-content-media',false,104857600,array['audio/mpeg','audio/mp4','video/mp4']);
insert into public.file_policies(bucket_id,purpose,access_mode,upload_protocol,max_bytes,owner_quota_bytes,allowed_mime_types,orphan_grace_hours,retention_days,malicious_content_policy)
values('miniapp-content-media','Audio and video published on Mini Program pages','signed','standard',104857600,10737418240,
  array['audio/mpeg','audio/mp4','video/mp4'],24,3650,'signature_only');
create function public.can_access_miniapp_content_media(p_path text,p_write boolean default false) returns boolean
language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
  if p_path is null or p_path !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(mp3|m4a|mp4)$' then return false; end if;
  if coalesce(public.has_perm(auth.uid(),'organization.profile.manage'),false) then return true; end if;
  if p_write is distinct from false then return false; end if;
  return exists(select 1 from miniapp_runtime_specs s where s.singleton and s.published is not null
    and jsonb_path_exists(s.published,'lax $.**.src ? (@ == $p)',jsonb_build_object('p',p_path)));
end $$;
create policy miniapp_content_media_write on storage.objects for insert to authenticated
  with check(bucket_id='miniapp-content-media' and public.can_access_miniapp_content_media(name,true));
create policy miniapp_content_media_read on storage.objects for select to anon,authenticated
  using(bucket_id='miniapp-content-media' and public.can_access_miniapp_content_media(name,false));
revoke all on function public.can_access_miniapp_content_media(text,boolean) from public;
grant execute on function public.can_access_miniapp_content_media(text,boolean) to anon,authenticated;

-- Posters, previewed images and share images are published images too.
do $copy$ begin
  execute replace(pg_get_functiondef('public.can_access_miniapp_content_image(text,boolean)'::regprocedure),
    'public.can_access_miniapp_content_image(', 'mathin_internal.can_access_miniapp_content_image_before_media(');
end $copy$;
revoke all on function mathin_internal.can_access_miniapp_content_image_before_media(text,boolean) from public,anon,authenticated;
create or replace function public.can_access_miniapp_content_image(p_path text,p_write boolean default false) returns boolean
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare base text;
begin
  if mathin_internal.can_access_miniapp_content_image_before_media(p_path,p_write) then return true; end if;
  if p_write is distinct from false or p_path is null or p_path !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(\.thumb)?\.webp$' then return false; end if;
  base:=replace(p_path,'.thumb.webp','.webp');
  return exists(select 1 from miniapp_runtime_specs s where s.singleton and s.published is not null
    and (jsonb_path_exists(s.published,'lax $.**.poster ? (@ == $p)',jsonb_build_object('p',base))
      or jsonb_path_exists(s.published,'lax $.**.images[*] ? (@ == $p)',jsonb_build_object('p',base))));
end $$;

-- Saving checks every uploaded image and media file the draft refers to.
create or replace function public.save_miniapp_runtime(p_spec jsonb,p_revision integer,p_publish boolean) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare r public.miniapp_runtime_specs; path text;
begin
  if not coalesce(public.has_perm(auth.uid(),'organization.profile.manage'),false) then raise exception 'FORBIDDEN'; end if;
  if p_revision is null or p_revision<0 or p_publish is null or not mathin_internal.valid_miniapp_runtime_spec(p_spec) then raise exception 'VALIDATION'; end if;
  perform pg_advisory_xact_lock(hashtextextended('miniapp-runtime',914));
  select * into r from miniapp_runtime_specs where singleton for update;
  if p_revision is distinct from coalesce(r.revision,0) then raise exception 'FORM_CHANGED'; end if;
  for path in select distinct value #>> '{}' from jsonb_path_query(p_spec,'lax $.**.image') value
      union select distinct value #>> '{}' from jsonb_path_query(p_spec,'lax $.**.icon') value
      union select distinct value #>> '{}' from jsonb_path_query(p_spec,'lax $.**.poster') value
      union select distinct value #>> '{}' from jsonb_path_query(p_spec,'lax $.**.images[*]') value loop
    if path ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.webp$'
      and not exists(select 1 from storage.objects where bucket_id='miniapp-content-images' and name=path) then raise exception 'VALIDATION'; end if;
  end loop;
  for path in select distinct value #>> '{}' from jsonb_path_query(p_spec,'lax $.**.src') value loop
    if path ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(mp3|m4a|mp4)$'
      and not exists(select 1 from storage.objects where bucket_id='miniapp-content-media' and name=path) then raise exception 'VALIDATION'; end if;
  end loop;
  insert into miniapp_runtime_specs(singleton,draft,published,revision,published_revision,published_at,updated_by)
    values(true,p_spec,case when p_publish then p_spec end,1,case when p_publish then 1 end,case when p_publish then now() end,auth.uid())
    on conflict(singleton) do update set draft=p_spec,revision=miniapp_runtime_specs.revision+1,
      published=case when p_publish then p_spec else miniapp_runtime_specs.published end,
      published_revision=case when p_publish then miniapp_runtime_specs.revision+1 else miniapp_runtime_specs.published_revision end,
      published_at=case when p_publish then now() else miniapp_runtime_specs.published_at end,updated_at=now(),updated_by=auth.uid();
  if p_publish then
    insert into miniapp_runtime_history(revision,spec,published_by) select revision,published,auth.uid() from miniapp_runtime_specs where singleton;
  end if;
  return public.miniapp_runtime_workbench();
end $$;

-- 4. Commands from runtime screens. The request id makes retries safe; the payload keeps what the family sent.
create table public.miniapp_runtime_events (
  id uuid primary key, owner_id uuid not null references public.profiles(id), participant_id uuid references public.students(id),
  command text not null check(command ~ '^[a-z][a-zA-Z0-9]*(\.[a-z][a-zA-Z0-9]*){0,3}$'),
  payload jsonb not null default '{}' check(jsonb_typeof(payload)='object' and octet_length(payload::text)<=16384),
  created_at timestamptz not null default now()
);
create index miniapp_runtime_events_owner on public.miniapp_runtime_events(owner_id,command,created_at desc);
create trigger miniapp_runtime_events_immutable before update or delete on public.miniapp_runtime_events
  for each row execute function public.reject_immutable_security_row();
alter table public.miniapp_runtime_events enable row level security;
revoke all on public.miniapp_runtime_events from public,anon,authenticated;
grant select on public.miniapp_runtime_events to authenticated;
create policy miniapp_runtime_events_read on public.miniapp_runtime_events for select to authenticated using(
  owner_id=(select auth.uid()) or coalesce(public.has_perm((select auth.uid()),'organization.profile.manage'),false));

create function public.miniapp_record_runtime_event(p_id uuid,p_command text,p_participant uuid,p_payload jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare r public.miniapp_runtime_events;
begin
  if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if;
  if p_id is null or p_command is null or p_payload is null then raise exception 'VALIDATION'; end if;
  if p_participant is not null and not coalesce(public.miniapp_can_participate(p_participant,'activities') or public.miniapp_can_participate(p_participant,'grades'),false) then
    raise exception 'FORBIDDEN';
  end if;
  select * into r from miniapp_runtime_events where id=p_id;
  if r.id is not null then
    if r.owner_id<>auth.uid() or r.command<>p_command then raise exception 'CONFLICT'; end if;
    return jsonb_build_object('id',r.id,'created',false,'createdAt',r.created_at);
  end if;
  if (select count(*) from miniapp_runtime_events where owner_id=auth.uid() and created_at>now()-interval '1 minute')>=30 then raise exception 'RATE_LIMIT'; end if;
  insert into miniapp_runtime_events(id,owner_id,participant_id,command,payload) values(p_id,auth.uid(),p_participant,p_command,p_payload) returning * into r;
  return jsonb_build_object('id',r.id,'created',true,'createdAt',r.created_at);
end $$;
revoke all on function public.miniapp_record_runtime_event(uuid,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.miniapp_record_runtime_event(uuid,text,uuid,jsonb) to authenticated;

-- 5. Form library: time, rating, address and file answers; a form outside a service may name one participant.
create or replace function mathin_internal.experience_answers_valid(f jsonb,a jsonb) returns boolean
language plpgsql immutable set search_path=public,pg_temp as $$
declare g jsonb; q jsonb; row jsonb; answer jsonb; c jsonb; other jsonb; key text; v text; visible boolean; empty boolean;
begin
  if jsonb_typeof(a) is distinct from 'object' or octet_length(a::text)>24576 then return false; end if;
  for key in select jsonb_object_keys(a) loop
    if not exists(select 1 from jsonb_array_elements(f->'groups') e where e->>'id'=key) then return false; end if;
  end loop;
  for g in select value from jsonb_array_elements(f->'groups') loop
    if jsonb_typeof(a->(g->>'id')) is distinct from 'array' then return false; end if;
    if jsonb_array_length(a->(g->>'id'))<(g->>'minEntries')::int
      or jsonb_array_length(a->(g->>'id'))>(case when g->'repeat'='true' then (g->>'maxEntries')::int else 1 end) then return false; end if;
    for row in select value from jsonb_array_elements(a->(g->>'id')) loop
      if jsonb_typeof(row)<>'object' then return false; end if;
      for key in select jsonb_object_keys(row) loop
        if not exists(select 1 from jsonb_array_elements(g->'fields') e where e->>'id'=key) then return false; end if;
      end loop;
      for q in select value from jsonb_array_elements(g->'fields') loop
        c:=q->'visibleWhen'; answer:=row->(q->>'id'); v:=answer#>>'{}'; other:=row->(c->>'fieldId');
        visible:=c is null or case c->>'operator'
          when 'answered' then coalesce(other<>'[]' and other<>'""' and other<>'null',false)
          when 'equals' then other=to_jsonb(c->>'value')
          when 'notEquals' then other is distinct from to_jsonb(c->>'value')
          when 'includes' then jsonb_typeof(other)='array' and other ? (c->>'value') else false end;
        empty:=answer is null or answer='[]' or jsonb_typeof(answer)='string' and btrim(v)='';
        if not coalesce(visible,false) then if not empty then return false; end if; continue; end if;
        if empty then if q->'required'='true' then return false; end if; continue; end if;
        if q->>'type'='multiselect' then
          if jsonb_typeof(answer)<>'array' or jsonb_array_length(answer)>30
            or jsonb_array_length(answer)<>(select count(distinct e) from jsonb_array_elements(answer) e)
            or exists(select 1 from jsonb_array_elements(answer) e where jsonb_typeof(e)<>'string'
              or not exists(select 1 from jsonb_array_elements(q->'options') o where to_jsonb(o->>'id')=e)) then return false; end if;
          continue;
        end if;
        -- Files are referenced by upload id; ownership is checked when the request is submitted.
        if q->>'type'='media' then
          if jsonb_typeof(answer)<>'array' or jsonb_array_length(answer)>coalesce((q->>'max')::int,9) or jsonb_array_length(answer)>9
            or jsonb_array_length(answer)<>(select count(distinct e) from jsonb_array_elements(answer) e)
            or exists(select 1 from jsonb_array_elements(answer) e where jsonb_typeof(e)<>'string'
              or e#>>'{}' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then return false; end if;
          continue;
        end if;
        if jsonb_typeof(answer)<>'string' or char_length(v)>(case when q->>'type'='textarea' then 4000 else 500 end) then return false; end if;
        if q->>'type'='select' and not exists(select 1 from jsonb_array_elements(q->'options') e where e->>'id'=v)
          or q->>'type'='consent' and v<>'yes'
          or q->>'type'='phone' and v !~ '^\+?[0-9 ()-]{6,30}$'
          or q->>'type'='email' and v !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
          or q->>'type'='time' and v !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
          or q->>'type'='rating' and (v !~ '^[0-9]{1,2}$' or v::int<1 or v::int>coalesce((q->>'max')::int,5)) then return false; end if;
        if q->>'type'='date' and (v !~ '^\d{4}-\d{2}-\d{2}$' or to_char(v::date,'YYYY-MM-DD')<>v) then return false; end if;
        if q->>'type'='number' and (v !~ '^-?[0-9]+(\.[0-9]+)?$' or q ? 'min' and v::numeric<(q->>'min')::numeric or q ? 'max' and v::numeric>(q->>'max')::numeric) then return false; end if;
      end loop;
    end loop;
  end loop;
  return true;
exception when others then return false;
end $$;

do $migration$
declare signature text := 'public.miniapp_submit_experience_request(uuid,text,text,integer,jsonb,uuid[],jsonb)'; definition text;
  previous text := 'elsif p_consents<>''{}'' or cardinality(p_participant_ids)>0 then raise exception ''VALIDATION'';';
  replacement text := 'elsif p_consents<>''{}'' or cardinality(p_participant_ids)>1 then raise exception ''VALIDATION'';';
begin
  definition := pg_get_functiondef(signature::regprocedure);
  if (length(definition)-length(replace(definition,previous,'')))/length(previous) <> 1 then raise exception 'FORM_PARTICIPANT_GUARD_CHANGED'; end if;
  execute replace(definition,previous,replacement);
end $migration$;

-- 7. Staff compare the draft with the complete published settings; the public publication omits form questions and contacts.
create function public.miniapp_settings_published_config() returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
  if not coalesce(public.has_perm(auth.uid(),'organization.profile.manage'),false) then raise exception 'FORBIDDEN'; end if;
  return (select published from miniapp_settings where singleton);
end $$;
revoke all on function public.miniapp_settings_published_config() from public,anon,authenticated;
grant execute on function public.miniapp_settings_published_config() to authenticated;

